import pytesseract
from PIL import Image, ImageOps, ImageFilter
import re

fname = 'receipt_0022.jpg'
img = Image.open(f'/app/workspace/dataset/img/{fname}')
w, h = img.size

for scale in [1, 2, 3]:
    img_s = img.resize((w*scale, h*scale), Image.Resampling.LANCZOS) if scale != 1 else img
    for pre in ['gray', 'auto', 'sharp', 'thresh128', 'thresh150', 'invert']:
        gray = ImageOps.grayscale(img_s)
        if pre == 'auto':
            v = ImageOps.autocontrast(gray)
        elif pre == 'sharp':
            v = ImageOps.autocontrast(gray).filter(ImageFilter.SHARPEN)
        elif pre == 'thresh128':
            v = gray.point(lambda p: 255 if p > 128 else 0)
        elif pre == 'thresh150':
            v = gray.point(lambda p: 255 if p > 150 else 0)
        elif pre == 'invert':
            v = ImageOps.invert(ImageOps.autocontrast(gray))
        else:
            v = gray
        for psm in [3, 4, 6, 11]:
            try:
                text = pytesseract.image_to_string(v, config=f'--psm {psm}')
            except:
                continue
            # Find date patterns
            dates = re.findall(r'\d{1,2}/\d{1,2}/\d{4}', text)
            if dates:
                # Find total
                for d in dates:
                    print(f"scale{scale} {pre} psm{psm}: {d}")
