from PIL import Image, ImageOps, ImageFilter
import re

fname = 'receipt_0022.jpg'
img = Image.open(f'/app/workspace/dataset/img/{fname}')
w, h = img.size

AMOUNT_RE = re.compile(r'(?<![\d.,])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2}|\d+,\d{2})(?![\d%])')

for scale in [1, 2]:
    img_s = img.resize((w*scale, h*scale), Image.Resampling.LANCZOS) if scale != 1 else img
    gray = ImageOps.grayscale(img_s)
    enh = ImageOps.autocontrast(gray)
    for psm in [3, 4, 6, 11, 12]:
        try:
            text = pytesseract.image_to_string(enh, config=f'--psm {psm}')
        except:
            continue
        # Find TOTAL related lines
        for line in text.split('\n'):
            if 'TOTAL' in line.upper() and not 'EXCLUDING' in line.upper() and not 'SUBTOTAL' in line.upper() and not 'TOTAL GST' in line.upper():
                amts = AMOUNT_RE.findall(line)
                if amts:
                    print(f"  scale{scale} psm{psm}: {line.strip()[:60]} → {amts}")
PYEOF", "security_risk": "LOW", "summary": "Check all TOTAL amounts across OCR variants for 0022", "timeout": 180}

